#!/usr/bin/env python3
"""Generate the agreed MeshDent site from maintained content and templates."""
import html
import json
from pathlib import Path
import components as c

BASE = Path(__file__).resolve().parent
OUT = BASE / 'generated'
OUT.mkdir(exist_ok=True)
for generated in OUT.glob("*.html"):
    generated.unlink()
SERVICES = json.loads((BASE/'content/services.json').read_text())
c.ASSETS = json.loads((BASE/'content/images.json').read_text())
img,link,esc = c.img,c.link,html.escape
PAGES=[]


def header(current):
    services=''.join(link(s['slug']+'.html',s['short'],'',suffix='') for s in SERVICES)
    nav=''.join(f'<a href="{slug}.html"'+(' aria-current="page"' if slug==current else '')+f'>{label}</a>' for slug,label in [('rolunk','Rólunk'),('munkaink','Munkáink'),('FreedomaAir','DOF Freedom Air')])
    return f'''<a class="skip" href="#tartalom">Ugrás a tartalomra</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="index.html" aria-label="MeshDent főoldal">{img('logo',True)}</a><button class="menu-button" aria-expanded="false" aria-controls="main-nav" type="button">Menü <span aria-hidden="true">☰</span></button><nav class="nav" id="main-nav" aria-label="Fő navigáció">{nav[:nav.index('<a href="munkaink')]}<details><summary>Szolgáltatások</summary><div class="nav-panel">{services}</div></details>{nav[nav.index('<a href="munkaink'):]}{link('kapcsolat.html','Kapcsolat','btn',suffix='')}</nav></div></header>'''


def footer():
    services=''.join(link(s['slug']+'.html',s['short'],'',suffix='') for s in SERVICES)
