def page(slug,title,description,body,kind='WebPage',service=None,chrome=True,noindex=False):
    route='/' if slug=='index' else '/'+slug
    url='__SITE_URL__'+route
    org={'@type':'Organization','@id':'__SITE_URL__/#organization','name':'MeshDent Kft.','url':'__SITE_URL__/','logo':'__SITE_URL__/assets/logo.png','email':'meshdentkft@gmail.com','telephone':['+36703619962','+36703534000'],'address':{'@type':'PostalAddress','streetAddress':'Petneházy u. 14.','postalCode':'1139','addressLocality':'Budapest','addressCountry':'HU'},'sameAs':['https://www.instagram.com/meshdent_lab_budapest/']}
    graph=[org,{'@type':'WebSite','@id':'__SITE_URL__/#website','url':'__SITE_URL__/','name':'MeshDent','inLanguage':'hu-HU','publisher':{'@id':org['@id']}},{'@type':kind,'@id':url+'#page','url':url,'name':title,'description':description,'inLanguage':'hu-HU','isPartOf':{'@id':'__SITE_URL__/#website'}}]
    if slug!='index': graph.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Főoldal','item':'__SITE_URL__/'},{'@type':'ListItem','position':2,'name':title,'item':url}]})
    if service:
        graph.append({'@type':'Service','name':service['title'],'description':service['intro'],'provider':{'@id':org['@id']},'url':url,'areaServed':{'@type':'City','name':'Budapest'}})
        graph.append({'@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in service['faq']]})
    structured=json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False).replace('<','\\u003c')
    resources='<script src="site-config.js" defer></script><script src="app.js" defer></script>' if chrome else ''
    if slug=='index': resources+='<script src="concepts.js" defer></script>'
    arrow='<svg class="v-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M5 19L19 5M5 5h14v14"/></svg>'
    document=f'''<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | MeshDent</title><meta name="description" content="{esc(description,quote=True)}"><meta name="robots" content="{'noindex, follow' if noindex else '__ROBOTS__'}"><meta name="theme-color" content="#1bb588"><link rel="canonical" href="{url}"><link rel="icon" href="assets/logo.png" type="image/png"><meta property="og:type" content="website"><meta property="og:locale" content="hu_HU"><meta property="og:site_name" content="MeshDent"><meta property="og:title" content="{esc(title,quote=True)} | MeshDent"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="__SITE_URL__/assets/full-arch.jpg"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="base.css"><link rel="stylesheet" href="concepts.css"><link rel="stylesheet" href="site.css">{resources}<script type="application/ld+json">{structured}</script></head><body class="meshdent-site">{header(slug) if chrome else ''}<main id="tartalom">{body}</main>{footer() if chrome else ''}</body></html>'''
    (OUT/(slug+'.html')).write_text(document.replace('↗',arrow))
    PAGES.append({'slug':slug,'route':route,'title':title,'noindex':noindex})


services=''.join(f'<a class="v-service-row" href="{s["slug"]}.html"><span>0{i}</span><div><h3>{esc(s["short"])}</h3><p>{esc(s["tag"])}</p></div><span aria-hidden="true">↗</span></a>' for i,s in enumerate(SERVICES,1))
