contact=c.breadcrumb('Kapcsolat')+'<section class="intro wrap"><p class="eyebrow">MeshDent / Budapest</p><h1>Közvetlenül a laborral.</h1><p class="lead">Egy új munkáról, egy technológiáról vagy az együttműködésről kérdezne? Elérhetőségeinket itt találja.</p></section>'+contact_section()+f'<section class="section wrap"><div class="section-head"><div><p class="eyebrow">Megközelítés</p><h2>Budapest, XIII. kerület.</h2><p class="muted">1139 Budapest, Petneházy u. 14.</p></div>{link("https://www.google.com/maps/search/?api=1&query=MeshDent+1139+Budapest+Petneh%C3%A1zy+14","Megnyitás a térképen")}</div></section>'
page('kapcsolat','Kapcsolat – fogtechnikai labor Budapesten','MeshDent: 1139 Budapest, Petneházy u. 14. Szabó Richárd és Buczi János telefonos elérhetősége, e-mail és kapcsolatfelvétel.',contact,'ContactPage')

patient=c.subhero('Digitális lenyomatvétel a fogpótlásához.','A digitális lenyomat a fogpótlás tervezésének egyik kiindulópontja. A MeshDent a kezelő fogorvossal együttműködve készíti el az egyedi fogtechnikai munkát.','freedom','Tájékoztatás pácienseknek','Tájékoztatást kérek','patient')
patient+='''<section class="section soft"><div class="wrap text-columns"><div><p class="eyebrow">A folyamat</p><h2>Érthetően, lépésről lépésre.</h2></div><div class="copy"><div class="copy-block"><h2>Adatfelvétel a rendelőben</h2><p>Az intraorális szkenner digitálisan rögzíti a szájüreg felszínét. A lenyomat és a fogorvossal egyeztetett adatok a fogtechnikai tervezést segítik.</p></div><div class="copy-block"><h2>DOF Freedom Air</h2><p>A DOF Freedom Air intraorális szkennelésre és fotogrammetriára alkalmas eszköz. Az adott esethez szükséges adatfelvételről a kezelőorvos és a labor egyeztet.</p></div><div class="copy-block"><h2>A kezelőorvosával együtt</h2><p>A megfelelő fogpótlásról, a vizsgálatról és a kezelés menetéről fogorvosa ad tájékoztatást. A MeshDent fogtechnikai labor, fogorvosi vizsgálatot és kezelést nem végez.</p></div></div></div></section>'''+c.cta_band('Tájékozódjon a lehetőségekről.','patient')
